const products = [
 {id:'climate',name:'Adaptive climate sensor',category:'Energy',type:'',icon:'23°',label:'IN BALANCE',tag:'A more aware home',desc:'Get a clearer picture of how your room feels throughout the day.',effort:1,renter:true,fit:'Understanding your space',how:'A small sensor could translate room conditions into easy-to-read patterns, helping you decide when to adjust your surroundings.',trade:'A sensor observes conditions; it does not control heating or guarantee energy savings.',next:'Think about which room feels hardest to keep comfortable.'},
 {id:'plug',name:'Energy-aware smart plug',category:'Energy',type:'plug',icon:'• •',label:'CONNECTED',tag:'Everyday energy',desc:'Make the energy habits of your everyday devices easier to understand.',effort:1,renter:true,fit:'Exploring device habits',how:'A connected outlet could show when a compatible device uses power and let you set a simple schedule.',trade:'Compatibility, electrical ratings, connectivity, and app requirements would need checking for any real product.',next:'List the devices you would want to understand before choosing a product.'},
 {id:'shower',name:'Water-feedback shower',category:'Water',type:'shower',icon:'≈',label:'FLOW',tag:'A mindful routine',desc:'See water use in the moment, without changing your whole routine.',effort:2,renter:false,fit:'Making routines visible',how:'A feedback display could make a shower’s water use visible while it is happening, giving you information at a useful moment.',trade:'Installation permission and plumbing compatibility may be needed. Feedback alone does not guarantee a change in use.',next:'Check whether changing your shower fittings is an option in your home.'},
 {id:'compost',name:'Countertop food recycler',category:'Everyday living',type:'compost',icon:'↻',label:'ANOTHER CYCLE',tag:'Rethink the leftovers',desc:'Explore a compact way to process kitchen scraps before their next step.',effort:2,renter:true,fit:'Rethinking food scraps',how:'A countertop concept could help make handling food scraps feel more manageable in a small kitchen.',trade:'Processing scraps is not the same as producing finished compost. Power use, filters, and an appropriate destination for the output matter.',next:'First consider where your food scraps or processed material would go.'},
 {id:'leak',name:'Quiet leak monitor',category:'Water',type:'leak',icon:'◉',label:'',tag:'A little peace of mind',desc:'Bring attention to unexpected water in those easy-to-miss places.',effort:1,renter:true,fit:'Noticing water sooner',how:'A small placed sensor could alert you when it detects water near a sink or appliance.',trade:'It only monitors the location where it is placed. It does not fix a leak or necessarily shut off water.',next:'Identify an accessible spot where unexpected water could go unnoticed.'},
 {id:'garden',name:'Self-watering herb planter',category:'Everyday living',type:'garden',icon:'♧',label:'ROOM TO GROW',tag:'Make room for green',desc:'Give a small growing habit a place on your windowsill.',effort:2,renter:true,fit:'Starting a small growing habit',how:'A reservoir-based planter could make watering herbs easier to incorporate into a daily routine.',trade:'Plants still need suitable light and regular care. A planter does not automatically reduce your environmental footprint.',next:'Notice how much light your chosen windowsill receives.'}
];
const $=s=>document.querySelector(s);let saved=new Set();let storageAvailable=true;
try{const data=JSON.parse(localStorage.getItem('sprout-saved')||'[]');if(Array.isArray(data))saved=new Set(data.filter(id=>products.some(p=>p.id===id)));}catch{storageAvailable=false;}
const compared=new Set();let category='All',savedView=false;
const effort=p=>p.effort===1?'Simple setup':'Some setup';
function announce(message){$('#announcement').textContent=message;}
function save(id){saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('sprout-saved',JSON.stringify([...saved]));}catch{storageAvailable=false;}announce(saved.has(id)?'Saved to your shortlist.'+(storageAvailable?'':' Saved for this visit only.'):'Removed from your shortlist.');render();if(savedView)showSaved();}
function render(){
 const query=$('#search').value.trim().toLowerCase();let list=products.filter(p=>(category==='All'||p.category===category)&&(!$('#renters').checked||p.renter)&&`${p.name} ${p.category} ${p.desc}`.toLowerCase().includes(query));
 if($('#sort').value==='effort')list.sort((a,b)=>a.effort-b.effort);if($('#sort').value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));
 $('#saved-count').textContent=saved.size;$('#result-count').textContent=`${list.length} ${list.length===1?'possibility':'possibilities'} to explore`;
 $('#products').innerHTML=list.length?list.map(p=>`<article class="card"><div class="product-art ${p.category==='Water'?'water':p.category==='Everyday living'?'living':''}"><span class="art-tag">${p.tag}</span><button class="save" data-save="${p.id}" aria-pressed="${saved.has(p.id)}" aria-label="${saved.has(p.id)?'Unsave':'Save'} ${p.name}">${saved.has(p.id)?'♥':'♡'}</button><div class="device ${p.type}" aria-hidden="true"><strong>${p.icon}</strong><small>${p.label}</small></div></div><div class="card-body"><p class="card-category">${p.category.toUpperCase()}</p><h3>${p.name}</h3><p class="description">${p.desc}</p><div class="specs"><span>${effort(p)}</span><span>${p.renter?'Renter-friendly':'Check permissions'}</span></div><div class="card-actions"><button data-detail="${p.id}" aria-label="Explore ${p.name}">Explore concept ↗</button><label><input type="checkbox" data-compare="${p.id}" ${compared.has(p.id)?'checked':''} aria-label="Compare ${p.name}"> Compare</label></div></div></article>`).join(''):'<div class="empty"><h3>No matches just yet.</h3><p>Try a broader search or reset your filters to see every possibility.</p><button class="primary" data-reset>Reset filters</button></div>';
 $('#compare-bar').hidden=compared.size===0;$('#compare-count').textContent=compared.size;$('#compare-open').disabled=compared.size<2;
 document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category===category));
}
function reset(){category='All';$('#search').value='';$('#renters').checked=false;$('#sort').value='curated';render();}
function modal(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
function details(id){savedView=false;const p=products.find(p=>p.id===id);modal(`<p class="eyebrow">${p.category.toUpperCase()} / ILLUSTRATIVE CONCEPT</p><h2>${p.name}</h2><p>${p.desc}</p><div class="specs"><span>${effort(p)}</span><span>${p.renter?'Renter-friendly':'Check permissions'}</span></div><h3>How it could help</h3><p>${p.how}</p><h3>What to consider</h3><p>${p.trade}</p><h3>A small first step</h3><p>${p.next}</p><button class="primary" data-detail-save="${p.id}">${saved.has(p.id)?'Remove from saved':'Save this concept'}</button><p><small>This is a design example, not a tested product or purchasing recommendation.</small></p>`);}
function showSaved(){savedView=true;modal(`<h2>Your saved possibilities.</h2><p>${storageAvailable?'Kept in this browser. No account needed.':'Browser storage is unavailable. Your choices last for this visit.'}</p>${saved.size?[...saved].map(id=>{const p=products.find(x=>x.id===id);return `<div class="saved-item"><div><h3>${p.name}</h3><p>${p.category} · ${effort(p)}</p><button class="text-button" data-detail="${id}">Explore concept →</button></div><button class="text-button" data-save="${id}" aria-label="Remove ${p.name} from saved">Remove</button></div>`;}).join(''):'<div class="empty"><h3>Make room for a possibility.</h3><p>Use the heart on any concept to save it here.</p><button class="primary" data-browse>Explore concepts →</button></div>'}`);}
function compare(){savedView=false;const list=products.filter(p=>compared.has(p.id));if(list.length<2)return;modal(`<h2>A little clarity, side by side.</h2><p>Compare practical fit. All details are illustrative.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Concept comparison, scroll horizontally on small screens"><table><caption class="sr-only">Comparison of selected sustainable technology concepts</caption><thead><tr><th scope="col">What matters</th>${list.map(p=>`<th scope="col">${p.name}</th>`).join('')}</tr></thead><tbody>${[['Useful for',p=>p.fit],['Setup',effort],['For renters',p=>p.renter?'Designed to be portable':'Check permissions first'],['Consider this',p=>p.trade],['First step',p=>p.next]].map(([label,value])=>`<tr><th scope="row">${label}</th>${list.map(p=>`<td>${value(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);}
function finder(){savedView=false;modal('<h2>Find a place to start.</h2><p>Two quick choices to narrow the possibilities. No personal information needed.</p><form id="finder-form"><fieldset><legend>1. What are you curious about?</legend><label class="choice"><input type="radio" name="interest" value="Energy" checked>Understanding energy use</label><label class="choice"><input type="radio" name="interest" value="Water">Being more mindful of water</label><label class="choice"><input type="radio" name="interest" value="Everyday living">Building a thoughtful everyday habit</label></fieldset><fieldset><legend>2. What fits your home?</legend><label class="choice"><input type="radio" name="home" value="portable" checked>Portable options, without installation</label><label class="choice"><input type="radio" name="home" value="any">I can explore options that need setup</label></fieldset><button class="primary" type="submit">Show my possibilities →</button></form>');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.save)save(b.dataset.save);if(b.dataset.detail)details(b.dataset.detail);if(b.dataset.detailSave){save(b.dataset.detailSave);details(b.dataset.detailSave);}if(b.hasAttribute('data-reset'))reset();if(b.hasAttribute('data-browse')){$('#dialog').close();$('#explore').scrollIntoView();$('#search').focus({preventScroll:true});}if(b.dataset.category){category=b.dataset.category;render();}});
document.addEventListener('change',e=>{if(e.target.dataset.compare){const id=e.target.dataset.compare;if(e.target.checked&&compared.size>=3){e.target.checked=false;announce('You can compare up to 3 concepts. Remove one before adding another.');savedView=false;modal('<h2>Keep your comparison focused.</h2><p>You can compare up to three concepts. Uncheck one of your selected concepts to make room for another.</p>');return;}e.target.checked?compared.add(id):compared.delete(id);$('#compare-bar').hidden=!compared.size;$('#compare-count').textContent=compared.size;$('#compare-open').disabled=compared.size<2;announce(`${compared.size} concepts selected. Select at least two to compare.`);}});
document.addEventListener('submit',e=>{if(e.target.id!=='finder-form')return;e.preventDefault();const data=new FormData(e.target);category=data.get('interest');$('#renters').checked=data.get('home')==='portable';$('#search').value='';render();$('#dialog').close();$('#explore').scrollIntoView();$('#search').focus({preventScroll:true});announce(`Your ${category.toLowerCase()} possibilities are ready.`);});
$('#search').addEventListener('input',render);$('#renters').addEventListener('change',render);$('#sort').addEventListener('change',render);$('#reset').onclick=reset;$('#finder').onclick=finder;$('#saved-nav').onclick=showSaved;$('#compare-open').onclick=compare;$('#compare-clear').onclick=()=>{compared.clear();render();$('#search').focus({preventScroll:true});};$('#close-dialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('close',()=>savedView=false);$('#about').onclick=()=>{savedView=false;modal('<h2>A concept with room to grow.</h2><p>Sprout is an independent UI/UX exploration of how people might discover and compare sustainable home technologies.</p><h3>The design question</h3><p>How might we help someone understand the practical fit of an unfamiliar technology, without technical overload or pressure to buy?</p><h3>What this prototype explores</h3><p>Plain-language descriptions, consistent comparison criteria, a short guided finder, and a private shortlist stored in the browser.</p><h3>What comes next</h3><p>These design assumptions have not yet been validated with users. Future work includes usability sessions, assistive-technology testing, and replacing illustrative concepts with verified product information.</p>');};render();
